#include "radar_service.h"

#include <algorithm>
#include <cstdint>
#include <cstdio>

#include "btstack.h"
#include "pico/cyw43_arch.h"

#include "radar_gatt.h" // generated from radar_gatt.gatt
#include "radar_protocol.h"
#include "uart_link.h"

namespace radar_service {

namespace {

/* ---- GATT handles (generated by the GATT compiler) ---- */
constexpr uint16_t kDataValueHandle =
    ATT_CHARACTERISTIC_F5D30002_3515_47D6_879D_3E34DE8F197A_01_VALUE_HANDLE;
constexpr uint16_t kDataCccHandle =
    ATT_CHARACTERISTIC_F5D30002_3515_47D6_879D_3E34DE8F197A_01_CLIENT_CONFIGURATION_HANDLE;
constexpr uint16_t kThresholdValueHandle =
    ATT_CHARACTERISTIC_F5D30003_3515_47D6_879D_3E34DE8F197A_01_VALUE_HANDLE;
constexpr uint16_t kStatusValueHandle =
    ATT_CHARACTERISTIC_F5D30004_3515_47D6_879D_3E34DE8F197A_01_VALUE_HANDLE;
constexpr uint16_t kStatusCccHandle =
    ATT_CHARACTERISTIC_F5D30004_3515_47D6_879D_3E34DE8F197A_01_CLIENT_CONFIGURATION_HANDLE;
constexpr uint16_t kTestValueHandle =
    ATT_CHARACTERISTIC_F5D30005_3515_47D6_879D_3E34DE8F197A_01_VALUE_HANDLE;

/* Application-specific ATT errors */
constexpr uint8_t kAttErrorRadarOffline = 0x80;   /* threshold write: radar link is down */
constexpr uint8_t kAttErrorNotSubscribed = 0x81;  /* throughput test: Radar Data not subscribed */

/* ---- Timing ---- */
constexpr uint32_t kTickMs = 50;
/*
 * A batch is sent once it is full or its oldest sample is this old.
 * Measured with 100 ms: at ~18 samples/s a packet at MTU 251 never
 * fills, so every sample waited 100-150 ms (avg ~120 ms) while the link
 * carried well under 1% of its capacity. 20 ms keeps latency low and
 * still merges samples that arrive together.
 */
constexpr uint32_t kMaxBatchDelayMs = 20;
/* UART is "offline" if no valid frame arrived for this long */
constexpr uint32_t kUartTimeoutMs = 1000;
constexpr uint32_t kStatusNotifyMs = 1000;
constexpr uint32_t kStatusLogMs = 5000;
constexpr uint32_t kLedToggleMs = 500;

/* ---- Connection parameters (interval in 1.25 ms units, timeout in 10 ms units) ---- */
/*
 * Requested shortly after connecting: 15-30 ms, latency 0, 4 s timeout.
 * Within Apple's accessory guidelines (min >= 15 ms, max >= min + 15 ms),
 * so iOS accepts it as well as Android.
 */
constexpr uint16_t kDefaultIntervalMin = 12;
constexpr uint16_t kDefaultIntervalMax = 24;
constexpr uint16_t kFastIntervalMin = 6;     /* 7.5 ms, for throughput tests */
constexpr uint16_t kFastIntervalMax = 12;    /* 15 ms */
constexpr uint16_t kSlowIntervalMin = 80;    /* 100 ms, low power */
constexpr uint16_t kSlowIntervalMax = 100;   /* 125 ms */
constexpr uint16_t kSupervisionTimeout = 400; /* 4 s */
/* Let the phone finish service discovery before asking for new parameters */
constexpr uint32_t kConnParamDelayMs = 2000;

/* ---- Throughput test ---- */
constexpr uint8_t kTestDefaultSeconds = 10;
constexpr uint8_t kTestMaxSeconds = 60;

/* ---- Radar Data packet layout ---- */
constexpr size_t kAttHeaderSize = 3;    /* opcode + handle */
constexpr size_t kPacketHeaderSize = 3; /* u16 sequence + u8 count */
constexpr size_t kSampleSize = 4;       /* u8 angle, u8 status, u16 distance */
constexpr uint16_t kMaxAttMtu = 251;    /* limited by HCI_ACL_PAYLOAD_SIZE */

/* ---- Link Status layout ---- */
constexpr size_t kStatusSize = 21;

/*
 * Advertising data, 31 bytes max:
 *   flags (3) + complete local name "RadarBLE" (10)
 *   + complete list of 128-bit service UUIDs (18) = 31
 * The UUID is stored little-endian (byte order reversed from the string).
 */
const uint8_t kAdvData[] = {
    0x02, BLUETOOTH_DATA_TYPE_FLAGS, 0x06,
    0x09, BLUETOOTH_DATA_TYPE_COMPLETE_LOCAL_NAME, 'R', 'a', 'd', 'a', 'r', 'B', 'L', 'E',
    0x11, BLUETOOTH_DATA_TYPE_COMPLETE_LIST_OF_128_BIT_SERVICE_CLASS_UUIDS,
    0x7A, 0x19, 0x8F, 0xDE, 0x34, 0x3E, 0x9D, 0x87,
    0xD6, 0x47, 0x15, 0x35, 0x01, 0x00, 0xD3, 0xF5,
};
static_assert(sizeof(kAdvData) <= 31, "advertising data too long");

/* Samples waiting to be notified, oldest first */
struct QueuedSample {
    radar::Sample sample;
    uint32_t received_ms;
};

constexpr size_t kQueueCapacity = 128;
QueuedSample queue[kQueueCapacity];
size_t queue_head = 0; /* index of the oldest sample */
size_t queue_count = 0;

/* ---- Connection state ---- */
hci_con_handle_t con_handle = HCI_CON_HANDLE_INVALID;
uint16_t att_mtu = ATT_DEFAULT_MTU;
uint16_t conn_interval = 0;      /* 1.25 ms units */
uint16_t conn_latency = 0;       /* connection events */
uint16_t supervision_timeout = 0; /* 10 ms units */
bool data_notify = false;
bool status_notify = false;
bool want_data = false;
bool want_status = false;
uint16_t data_seq = 0;

/* ---- Radar link state ---- */
uint32_t good_frames = 0;
uint32_t bad_frames = 0;
uint32_t dropped_samples = 0;
uint32_t last_frame_ms = 0;
bool any_frame = false;
bool uart_online = false;
bool thresholds_known = false;
radar::Thresholds thresholds{0, 0};

/* ---- Connection-interval request ---- */
uint32_t connected_ms = 0;
bool conn_params_requested = false;

/* ---- Latency: UART frame received -> notification accepted by BTstack ---- */
uint32_t latency_sum_ms = 0;
uint32_t latency_count = 0;
uint32_t latency_max_ms = 0;

/* ---- Throughput test ---- */
bool test_active = false;
uint32_t test_start_ms = 0;
uint32_t test_end_ms = 0;
uint32_t test_bytes = 0;
uint32_t test_packets = 0;

btstack_packet_callback_registration_t hci_event_registration;
btstack_timer_source_t tick_timer;
/* One-shot timer that fires when the oldest queued sample reaches kMaxBatchDelayMs */
btstack_timer_source_t flush_timer;
bool flush_timer_armed = false;
uint32_t last_status_notify_ms = 0;
uint32_t last_status_log_ms = 0;
uint32_t last_led_ms = 0;
bool led_on = false;

uint32_t now_ms()
{
    return btstack_run_loop_get_time_ms();
}

bool connected()
{
    return con_handle != HCI_CON_HANDLE_INVALID;
}

/* How many samples fit in one notification at the current MTU */
size_t samples_per_packet()
{
    const size_t payload = att_mtu - kAttHeaderSize;
    if (payload <= kPacketHeaderSize) {
        return 0;
    }
    return std::min((payload - kPacketHeaderSize) / kSampleSize, kQueueCapacity);
}

void queue_clear()
{
    queue_head = 0;
    queue_count = 0;
    if (flush_timer_armed) {
        btstack_run_loop_remove_timer(&flush_timer);
        flush_timer_armed = false;
    }
}

void queue_push(const radar::Sample &s)
{
    if (queue_count == kQueueCapacity) {
        /* Link can't keep up: drop the oldest so the newest data gets through */
        queue_head = (queue_head + 1) % kQueueCapacity;
        --queue_count;
        ++dropped_samples;
    }
    queue[(queue_head + queue_count) % kQueueCapacity] = {s, now_ms()};
    ++queue_count;
}

void request_send()
{
    if (connected() && (want_data || want_status || test_active)) {
        att_server_request_can_send_now_event(con_handle);
    }
}

size_t build_status(uint8_t *buf)
{
    buf[0] = uart_online ? 1 : 0;
    little_endian_store_32(buf, 1, good_frames);
    little_endian_store_32(buf, 5, bad_frames);
    little_endian_store_32(buf, 9, dropped_samples);
    little_endian_store_16(buf, 13, conn_interval);
    little_endian_store_16(buf, 15, conn_latency);
    little_endian_store_16(buf, 17, supervision_timeout);
    little_endian_store_16(buf, 19, att_mtu);
    return kStatusSize;
}

void send_status()
{
    uint8_t buf[kStatusSize];
    const size_t len = std::min<size_t>(build_status(buf), att_mtu - kAttHeaderSize);

    if (att_server_notify(con_handle, kStatusValueHandle, buf, len) == ERROR_CODE_SUCCESS) {
        want_status = false;
        last_status_notify_ms = now_ms();
    }
}

void flush_timer_handler(btstack_timer_source_t *ts)
{
    (void)ts;
    flush_timer_armed = false;
    if (data_notify && queue_count > 0) {
        want_data = true;
        request_send();
    }
}

/*
 * Arm the flush timer for the oldest queued sample, exactly when it
 * reaches kMaxBatchDelayMs. Replaces checking the age on the 50 ms tick,
 * which added up to 50 ms of extra wait.
 */
void arm_flush_timer()
{
    if (flush_timer_armed) {
        btstack_run_loop_remove_timer(&flush_timer);
        flush_timer_armed = false;
    }
    if (queue_count == 0) {
        return;
    }

    const uint32_t age = now_ms() - queue[queue_head].received_ms;
    const uint32_t wait = age >= kMaxBatchDelayMs ? 0 : kMaxBatchDelayMs - age;

    btstack_run_loop_set_timer(&flush_timer, wait);
    btstack_run_loop_add_timer(&flush_timer);
    flush_timer_armed = true;
}

/* Send one batch from the front of the queue; samples leave the queue only if sent */
void send_data_batch()
{
    const size_t n = std::min(queue_count, samples_per_packet());
    if (n == 0) {
        want_data = false;
        return;
    }

    uint8_t buf[kMaxAttMtu];
    little_endian_store_16(buf, 0, data_seq);
    buf[2] = static_cast<uint8_t>(n);

    for (size_t i = 0; i < n; ++i) {
        const radar::Sample &s = queue[(queue_head + i) % kQueueCapacity].sample;
        uint8_t *p = buf + kPacketHeaderSize + i * kSampleSize;
        p[0] = s.angle_deg;
        p[1] = static_cast<uint8_t>(s.status);
        little_endian_store_16(p, 2, s.distance_mm);
    }

    const size_t len = kPacketHeaderSize + n * kSampleSize;
    if (att_server_notify(con_handle, kDataValueHandle, buf, len) != ERROR_CODE_SUCCESS) {
        return; /* no buffer space; try again on the next CAN_SEND_NOW */
    }

    ++data_seq;

    const uint32_t now = now_ms();
    for (size_t i = 0; i < n; ++i) {
        const uint32_t waited = now - queue[(queue_head + i) % kQueueCapacity].received_ms;
        latency_sum_ms += waited;
        latency_max_ms = std::max(latency_max_ms, waited);
    }
    latency_count += n;

    queue_head = (queue_head + n) % kQueueCapacity;
    queue_count -= n;
    want_data = queue_count >= samples_per_packet() && queue_count > 0;
    arm_flush_timer(); /* for whatever is still queued */
}

/*
 * Throughput test: fill every notification to the current MTU with
 * synthetic samples, as fast as BTstack can take them, and measure the
 * application bytes delivered per second.
 */
void send_test_packet()
{
    const size_t n = samples_per_packet();
    if (n == 0) {
        return;
    }

    uint8_t buf[kMaxAttMtu];
    little_endian_store_16(buf, 0, data_seq);
    buf[2] = static_cast<uint8_t>(n);
    for (size_t i = 0; i < n; ++i) {
        uint8_t *p = buf + kPacketHeaderSize + i * kSampleSize;
        p[0] = static_cast<uint8_t>(i % 181);
        p[1] = static_cast<uint8_t>(radar::Status::Ok);
        little_endian_store_16(p, 2, static_cast<uint16_t>(test_packets & 0xFFFF));
    }

    const size_t len = kPacketHeaderSize + n * kSampleSize;
    if (att_server_notify(con_handle, kDataValueHandle, buf, len) == ERROR_CODE_SUCCESS) {
        ++data_seq;
        ++test_packets;
        test_bytes += len;
    }
}

void finish_test(const char *reason)
{
    if (!test_active) {
        return;
    }
    test_active = false;

    const uint32_t elapsed = std::max<uint32_t>(now_ms() - test_start_ms, 1);
    /* bytes * 8 / ms = kbit/s; keep one decimal without floating point */
    const uint32_t kbit_x10 = static_cast<uint32_t>(
        static_cast<uint64_t>(test_bytes) * 80u / elapsed);
    const uint32_t interval_x100 = conn_interval * 125u;

    printf("Throughput test %s: %lu packets, %lu bytes in %lu ms = %lu.%lu kbit/s "
           "(mtu %u, %u samples/packet, interval %lu.%02lu ms)\n",
           reason, static_cast<unsigned long>(test_packets),
           static_cast<unsigned long>(test_bytes), static_cast<unsigned long>(elapsed),
           static_cast<unsigned long>(kbit_x10 / 10), static_cast<unsigned long>(kbit_x10 % 10),
           att_mtu, static_cast<unsigned>(samples_per_packet()),
           static_cast<unsigned long>(interval_x100 / 100),
           static_cast<unsigned long>(interval_x100 % 100));
}

void request_conn_params(uint16_t min, uint16_t max, const char *label)
{
    if (!connected()) {
        return;
    }
    printf("Requesting connection interval %s\n", label);
    gap_request_connection_parameter_update(con_handle, min, max, 0, kSupervisionTimeout);
}

void start_advertising()
{
    /* 100-200 ms advertising interval, in 0.625 ms units */
    const uint16_t adv_int_min = 160;
    const uint16_t adv_int_max = 320;
    const uint8_t adv_type = 0; /* ADV_IND: connectable, undirected */
    bd_addr_t null_addr = {};

    gap_advertisements_set_params(adv_int_min, adv_int_max, adv_type, 0, null_addr, 0x07, 0x00);
    gap_advertisements_set_data(sizeof(kAdvData), const_cast<uint8_t *>(kAdvData));
    gap_advertisements_enable(1);
    printf("Advertising as RadarBLE\n");
}

void print_conn_params(const char *what)
{
    /* interval x 1.25 ms, printed with two decimals without floating point */
    const uint32_t interval_x100 = conn_interval * 125u;
    printf("%s: interval %lu.%02lu ms, latency %u, timeout %u ms\n", what,
           static_cast<unsigned long>(interval_x100 / 100),
           static_cast<unsigned long>(interval_x100 % 100), conn_latency,
           supervision_timeout * 10u);
}

void handle_le_meta(const uint8_t *packet)
{
    switch (hci_event_le_meta_get_subevent_code(packet)) {
    case HCI_SUBEVENT_LE_CONNECTION_COMPLETE:
        if (hci_subevent_le_connection_complete_get_status(packet) != ERROR_CODE_SUCCESS) {
            break;
        }
        conn_interval = hci_subevent_le_connection_complete_get_conn_interval(packet);
        conn_latency = hci_subevent_le_connection_complete_get_conn_latency(packet);
        supervision_timeout = hci_subevent_le_connection_complete_get_supervision_timeout(packet);
        print_conn_params("Connection parameters");
        break;

    case HCI_SUBEVENT_LE_CONNECTION_UPDATE_COMPLETE:
        if (hci_subevent_le_connection_update_complete_get_status(packet) != ERROR_CODE_SUCCESS) {
            break;
        }
        conn_interval = hci_subevent_le_connection_update_complete_get_conn_interval(packet);
        conn_latency = hci_subevent_le_connection_update_complete_get_conn_latency(packet);
        supervision_timeout =
            hci_subevent_le_connection_update_complete_get_supervision_timeout(packet);
        print_conn_params("Connection parameters updated");
        want_status = status_notify;
        request_send();
        break;

    case HCI_SUBEVENT_LE_DATA_LENGTH_CHANGE:
        printf("Data length changed: tx %u, rx %u octets\n",
               hci_subevent_le_data_length_change_get_max_tx_octets(packet),
               hci_subevent_le_data_length_change_get_max_rx_octets(packet));
        break;

    default:
        break;
    }
}

/*
 * HCI events: stack state and LE meta events (connection parameters,
 * data length). Kept apart from the ATT handler so each event is
 * handled once - with one shared handler the connection-complete event
 * was seen twice.
 */
void hci_packet_handler(uint8_t packet_type, uint16_t channel, uint8_t *packet, uint16_t size)
{
    (void)channel;
    (void)size;

    if (packet_type != HCI_EVENT_PACKET) {
        return;
    }

    switch (hci_event_packet_get_type(packet)) {
    case BTSTACK_EVENT_STATE: {
        if (btstack_event_state_get_state(packet) != HCI_STATE_WORKING) {
            break;
        }
        bd_addr_t local_addr;
        gap_local_bd_addr(local_addr);
        printf("BTstack up, address %s\n", bd_addr_to_str(local_addr));
        start_advertising();
        break;
    }

    case HCI_EVENT_LE_META:
        handle_le_meta(packet);
        break;

    default:
        break;
    }
}

/* ATT server events: connection lifecycle, MTU, flow control */
void att_packet_handler(uint8_t packet_type, uint16_t channel, uint8_t *packet, uint16_t size)
{
    (void)channel;
    (void)size;

    if (packet_type != HCI_EVENT_PACKET) {
        return;
    }

    switch (hci_event_packet_get_type(packet)) {
    case ATT_EVENT_CONNECTED:
        con_handle = att_event_connected_get_handle(packet);
        att_mtu = att_server_get_mtu(con_handle);
        connected_ms = now_ms();
        conn_params_requested = false;
        printf("Connected, handle 0x%04x\n", con_handle);
        break;

    case ATT_EVENT_MTU_EXCHANGE_COMPLETE:
        att_mtu = att_event_mtu_exchange_complete_get_MTU(packet);
        printf("MTU exchanged: %u (%u samples per notification)\n", att_mtu,
               static_cast<unsigned>(samples_per_packet()));
        want_status = status_notify;
        request_send();
        break;

    case ATT_EVENT_DISCONNECTED:
        finish_test("aborted by disconnect");
        printf("Disconnected\n");
        con_handle = HCI_CON_HANDLE_INVALID;
        att_mtu = ATT_DEFAULT_MTU;
        data_notify = false;
        status_notify = false;
        want_data = false;
        want_status = false;
        queue_clear();
        /* BTstack resumes advertising by itself after a disconnect */
        break;

    case ATT_EVENT_CAN_SEND_NOW:
        /* Status first: it is small and infrequent */
        if (want_status && status_notify) {
            send_status();
        } else if (test_active) {
            send_test_packet();
        } else if (want_data && data_notify) {
            send_data_batch();
        }
        request_send();
        break;

    default:
        break;
    }
}

uint16_t att_read_callback(hci_con_handle_t connection_handle, uint16_t att_handle,
                           uint16_t offset, uint8_t *buffer, uint16_t buffer_size)
{
    (void)connection_handle;

    if (att_handle == kThresholdValueHandle) {
        uint8_t value[4];
        little_endian_store_16(value, 0, thresholds_known ? thresholds.warn_mm : 0);
        little_endian_store_16(value, 2, thresholds_known ? thresholds.danger_mm : 0);
        return att_read_callback_handle_blob(value, sizeof(value), offset, buffer, buffer_size);
    }

    if (att_handle == kStatusValueHandle) {
        uint8_t value[kStatusSize];
        build_status(value);
        return att_read_callback_handle_blob(value, sizeof(value), offset, buffer, buffer_size);
    }

    return 0;
}

int write_thresholds(const uint8_t *buffer, uint16_t buffer_size)
{
    if (buffer_size != 4) {
        return ATT_ERROR_INVALID_ATTRIBUTE_VALUE_LENGTH;
    }

    const radar::Thresholds t{little_endian_read_16(buffer, 0), little_endian_read_16(buffer, 2)};

    if (!radar::thresholds_valid(t)) {
        printf("Threshold write rejected: warn %u, danger %u\n", t.warn_mm, t.danger_mm);
        return ATT_ERROR_VALUE_NOT_ALLOWED;
    }

    if (!uart_online) {
        printf("Threshold write rejected: radar link offline\n");
        return kAttErrorRadarOffline;
    }

    char cmd[32];
    const size_t len = radar::format_set_thresholds(t, cmd, sizeof(cmd));
    uart_link::send(cmd, len);
    printf("Thresholds sent to radar: warn %u, danger %u\n", t.warn_mm, t.danger_mm);
    return 0;
}

int write_test_control(const uint8_t *buffer, uint16_t buffer_size)
{
    if (buffer_size < 1 || buffer_size > 2) {
        return ATT_ERROR_INVALID_ATTRIBUTE_VALUE_LENGTH;
    }

    switch (buffer[0]) {
    case 0x00:
        finish_test("stopped");
        return 0;

    case 0x01: {
        if (!data_notify) {
            printf("Throughput test refused: subscribe to Radar Data first\n");
            return kAttErrorNotSubscribed;
        }
        const uint8_t seconds = buffer_size == 2 ? buffer[1] : kTestDefaultSeconds;
        if (seconds == 0 || seconds > kTestMaxSeconds) {
            return ATT_ERROR_VALUE_NOT_ALLOWED;
        }
        queue_clear(); /* real samples pause during the test */
        want_data = false;
        test_active = true;
        test_bytes = 0;
        test_packets = 0;
        test_start_ms = now_ms();
        test_end_ms = test_start_ms + seconds * 1000u;
        printf("Throughput test started for %u s\n", seconds);
        request_send();
        return 0;
    }

    case 0x02:
        request_conn_params(kFastIntervalMin, kFastIntervalMax, "7.5-15 ms (fast)");
        return 0;

    case 0x03:
        request_conn_params(kDefaultIntervalMin, kDefaultIntervalMax, "15-30 ms (default)");
        return 0;

    case 0x04:
        request_conn_params(kSlowIntervalMin, kSlowIntervalMax, "100-125 ms (slow)");
        return 0;

    default:
        return ATT_ERROR_VALUE_NOT_ALLOWED;
    }
}

int att_write_callback(hci_con_handle_t connection_handle, uint16_t att_handle,
                       uint16_t transaction_mode, uint16_t offset, uint8_t *buffer,
                       uint16_t buffer_size)
{
    if (att_handle == kThresholdValueHandle) {
        /* Values are 4 bytes; long/queued writes are not needed */
        if (transaction_mode != ATT_TRANSACTION_MODE_NONE) {
            return ATT_ERROR_REQUEST_NOT_SUPPORTED;
        }
        if (offset != 0) {
            return ATT_ERROR_INVALID_OFFSET;
        }
        return write_thresholds(buffer, buffer_size);
    }

    if (att_handle == kTestValueHandle) {
        if (transaction_mode != ATT_TRANSACTION_MODE_NONE) {
            return ATT_ERROR_REQUEST_NOT_SUPPORTED;
        }
        return write_test_control(buffer, buffer_size);
    }

    if ((att_handle == kDataCccHandle || att_handle == kStatusCccHandle) && buffer_size >= 2) {
        const bool enabled = little_endian_read_16(buffer, 0) ==
                             GATT_CLIENT_CHARACTERISTICS_CONFIGURATION_NOTIFICATION;
        con_handle = connection_handle;

        if (att_handle == kDataCccHandle) {
            data_notify = enabled;
            queue_clear(); /* start fresh, no stale samples */
            printf("Radar data notifications %s\n", enabled ? "on" : "off");
        } else {
            status_notify = enabled;
            want_status = enabled;
            printf("Link status notifications %s\n", enabled ? "on" : "off");
            request_send();
        }
    }

    return 0;
}

void set_uart_online(bool online)
{
    if (online == uart_online) {
        return;
    }
    uart_online = online;
    printf("Radar link %s\n", online ? "online" : "OFFLINE");

    if (online) {
        /* Ask the Nucleo for its current thresholds */
        char cmd[16];
        const size_t len = radar::format_query_thresholds(cmd, sizeof(cmd));
        uart_link::send(cmd, len);
    }

    want_status = status_notify;
    request_send();
}

void tick_handler(btstack_timer_source_t *ts)
{
    const uint32_t now = now_ms();

    set_uart_online(any_frame && now - last_frame_ms < kUartTimeoutMs);

    if (test_active && static_cast<int32_t>(now - test_end_ms) >= 0) {
        finish_test("done");
    }

    if (connected() && !conn_params_requested && now - connected_ms >= kConnParamDelayMs) {
        conn_params_requested = true;
        request_conn_params(kDefaultIntervalMin, kDefaultIntervalMax, "15-30 ms (default)");
    }

    /* Safety net: the flush timer normally handles partial batches */
    if (data_notify && queue_count > 0 && !flush_timer_armed &&
        now - queue[queue_head].received_ms >= kMaxBatchDelayMs) {
        want_data = true;
    }

    if (status_notify && now - last_status_notify_ms >= kStatusNotifyMs) {
        want_status = true;
    }

    request_send();

    if (now - last_led_ms >= kLedToggleMs) {
        last_led_ms = now;
        led_on = !led_on;
        cyw43_arch_gpio_put(CYW43_WL_GPIO_LED_PIN, led_on);
    }

    if (now - last_status_log_ms >= kStatusLogMs) {
        last_status_log_ms = now;
        printf("[status] uart=%s good=%lu bad=%lu dropped=%lu conn=%s data=%s mtu=%u",
               uart_online ? "online" : "offline", static_cast<unsigned long>(good_frames),
               static_cast<unsigned long>(bad_frames),
               static_cast<unsigned long>(dropped_samples), connected() ? "yes" : "no",
               data_notify ? "on" : "off", att_mtu);

        /* Queueing latency of the samples notified in the last window */
        if (latency_count > 0) {
            printf(" latency avg=%lu max=%lu ms (n=%lu)",
                   static_cast<unsigned long>(latency_sum_ms / latency_count),
                   static_cast<unsigned long>(latency_max_ms),
                   static_cast<unsigned long>(latency_count));
            latency_sum_ms = 0;
            latency_count = 0;
            latency_max_ms = 0;
        }
        printf("\n");
    }

    btstack_run_loop_set_timer(ts, kTickMs);
    btstack_run_loop_add_timer(ts);
}

} // namespace

void init()
{
    att_server_init(profile_data, att_read_callback, att_write_callback);

    hci_event_registration.callback = &hci_packet_handler;
    hci_add_event_handler(&hci_event_registration);
    att_server_register_packet_handler(att_packet_handler);

    flush_timer.process = &flush_timer_handler;

    tick_timer.process = &tick_handler;
    btstack_run_loop_set_timer(&tick_timer, kTickMs);
    btstack_run_loop_add_timer(&tick_timer);
}

void on_uart_line(std::string_view line, bool complete)
{
    const auto frame = complete ? radar::parse_line(line) : std::nullopt;

    if (!frame) {
        ++bad_frames;
        return;
    }

    ++good_frames;
    any_frame = true;
    last_frame_ms = now_ms();

    switch (frame->kind) {
    case radar::Frame::Kind::Sample:
        if (data_notify && !test_active) {
            const bool was_empty = queue_count == 0;
            queue_push(frame->sample);
            if (was_empty) {
                arm_flush_timer();
            }
            if (queue_count >= samples_per_packet()) {
                want_data = true;
                request_send();
            }
        }
        break;

    case radar::Frame::Kind::Thresholds:
        thresholds = frame->thresholds;
        thresholds_known = true;
        printf("Radar thresholds: warn %u, danger %u\n", thresholds.warn_mm,
               thresholds.danger_mm);
        break;
    }
}

} // namespace radar_service
